// Finds every PDF on the incoming email / form upload and builds the request for the AI.
const PROMPT = `You are an accounts-payable assistant. Extract the data from this supplier invoice.
Rules:
- Copy values exactly as printed. Do not guess or calculate anything that is not printed.
- Numbers: digits only, no currency symbols or commas (e.g. 45194.00).
- po_number is the BUYER's purchase order reference. It may be labelled "PO Number", "Order Ref", or appear in the notes/footer. Return "" if it is not on the invoice.
- vendor_name is the company that ISSUED the invoice (the seller), not the customer.
- One entry in line_items per billed line.`;

const SCHEMA = {
  type: 'OBJECT',
  properties: {
    vendor_name: { type: 'STRING' },
    invoice_number: { type: 'STRING' },
    invoice_date: { type: 'STRING' },
    po_number: { type: 'STRING' },
    line_items: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          description: { type: 'STRING' },
          quantity: { type: 'NUMBER' },
          unit_price: { type: 'NUMBER' },
          amount: { type: 'NUMBER' },
        },
        required: ['description', 'quantity', 'unit_price', 'amount'],
      },
    },
    subtotal: { type: 'NUMBER' },
    tax_rate_percent: { type: 'NUMBER' },
    tax_amount: { type: 'NUMBER' },
    total: { type: 'NUMBER' },
  },
  required: ['vendor_name', 'invoice_number', 'po_number', 'line_items', 'subtotal', 'tax_amount', 'total'],
};

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaries = item.binary || {};
  for (const key of Object.keys(binaries)) {
    const b = binaries[key];
    const name = b.fileName || key;
    const isPdf = String(b.mimeType || '').includes('pdf') || name.toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    out.push({
      json: {
        file_name: name,
        source: item.json.subject !== undefined ? 'email' : 'upload',
        email_from: (item.json.from && (item.json.from.text || item.json.from)) || '',
        gemini_request: {
          contents: [{
            parts: [
              { inline_data: { mime_type: 'application/pdf', data: buffer.toString('base64') } },
              { text: PROMPT },
            ],
          }],
          generationConfig: {
            temperature: 0,
            responseMimeType: 'application/json',
            responseSchema: SCHEMA,
          },
        },
      },
    });
  }
}
return out;

// Turns the AI's reply into clean invoice data. If the AI call failed, the error is kept
// so the invoice gets flagged for a human instead of silently disappearing.
const prepared = $('Prepare PDF for AI').all();
return $input.all().map((item, i) => {
  const meta = (prepared[i] && prepared[i].json) || {};
  let invoice = null;
  let extraction_error = '';
  try {
    if (item.json.error) throw new Error(JSON.stringify(item.json.error).slice(0, 200));
    const text = item.json.candidates[0].content.parts.map(p => p.text || '').join('');
    invoice = JSON.parse(text);
  } catch (e) {
    extraction_error = 'AI could not read this invoice (' + e.message + ')';
  }
  return {
    json: {
      file_name: meta.file_name || '',
      source: meta.source || '',
      email_from: meta.email_from || '',
      extraction_error,
      invoice,
    },
  };
});

// ============ SETTINGS (change these to tune the agent) ============
const GST_RATE = 0.18;            // expected GST on every PO
const AMOUNT_TOLERANCE_RS = 2;    // rounding allowed on totals
const PRICE_TOLERANCE_PCT = 0.5;  // allowed unit-price difference
const VENDOR_MATCH_MIN = 0.6;     // how similar vendor names must be (0-1)
const ITEM_MATCH_MIN = 0.5;       // how similar item names must be (0-1)
// ===================================================================
// The AI only READS the invoice. Every approve/flag decision below is a fixed rule,
// so the same invoice always gets the same answer and every decision can be explained.

const STOP = new Set(['pvt', 'ltd', 'private', 'limited', 'co', 'company', 'the', 'and', 'of', 'inc', 'llp']);
const tokens = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').split(' ')
  .filter(t => t && !STOP.has(t)).map(t => (t.length > 3 && t.endsWith('s') ? t.slice(0, -1) : t));
function similarity(a, b) {
  const A = new Set(tokens(a)), B = new Set(tokens(b));
  if (!A.size || !B.size) return 0;
  let common = 0;
  for (const t of A) if (B.has(t)) common++;
  return common / Math.min(A.size, B.size);
}
const num = v => Number(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0;
const rs = v => 'Rs.' + num(v).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const normId = s => String(s || '').trim().toUpperCase();
const vendorKey = s => tokens(s).join(' ');

const poRows = $('Get POs').all().map(i => i.json).filter(r => r.po_number);
const logRows = $('Get Log').all().map(i => i.json).filter(r => r.invoice_number);
const seen = new Set(logRows.map(r => normId(r.invoice_number) + '|' + vendorKey(r.vendor)));

const results = [];
for (const { json: x } of $('Parse AI Output').all()) {
  const reasons = [];
  const inv = x.invoice || {};
  let expected = 0;

  if (x.extraction_error) reasons.push(x.extraction_error);
  else {
    // 1) Did the AI read the invoice properly? Check the invoice's own maths.
    const lines = (inv.line_items || []).map(li => ({ description: li.description, qty: num(li.quantity), price: num(li.unit_price) }));
    const missing = ['invoice_number', 'vendor_name', 'total'].filter(f => !inv[f]);
    if (!lines.length) missing.push('line items');
    if (missing.length) reasons.push('AI could not find: ' + missing.join(', '));
    const lineSum = lines.reduce((s, l) => s + l.qty * l.price, 0);
    if (lines.length && Math.abs(lineSum - num(inv.subtotal)) > AMOUNT_TOLERANCE_RS)
      reasons.push(`Reading check failed: items add up to ${rs(lineSum)} but subtotal reads ${rs(inv.subtotal)}`);
    if (Math.abs(num(inv.subtotal) + num(inv.tax_amount) - num(inv.total)) > AMOUNT_TOLERANCE_RS)
      reasons.push(`Reading check failed: subtotal + tax does not equal total ${rs(inv.total)}`);

    // 2) Already processed?
    const dupKey = normId(inv.invoice_number) + '|' + vendorKey(inv.vendor_name);
    if (inv.invoice_number && seen.has(dupKey)) reasons.push(`Duplicate: invoice ${inv.invoice_number} was already processed`);
    seen.add(dupKey);

    // 3) Match against the purchase order
    const poNum = normId(inv.po_number);
    const poLines = poRows.filter(r => normId(r.po_number) === poNum);
    if (!poNum) reasons.push('No PO number found on the invoice');
    else if (!poLines.length) reasons.push(`PO ${poNum} not found in the PO sheet`);
    else {
      const poVendor = poLines[0].vendor;
      if (similarity(inv.vendor_name, poVendor) < VENDOR_MATCH_MIN)
        reasons.push(`Vendor mismatch: invoice is from "${inv.vendor_name}" but ${poNum} is with "${poVendor}"`);

      const used = new Set();
      let lineIssue = false;
      for (const li of lines) {
        let best = -1, bestScore = 0;
        poLines.forEach((p, idx) => {
          if (used.has(idx)) return;
          const s = similarity(li.description, p.item_description);
          if (s > bestScore) { bestScore = s; best = idx; }
        });
        if (best < 0 || bestScore < ITEM_MATCH_MIN) {
          reasons.push(`Item not on PO: "${li.description}" (${li.qty} x ${rs(li.price)})`);
          lineIssue = true; continue;
        }
        used.add(best);
        const p = poLines[best], pq = num(p.quantity), pp = num(p.unit_price);
        expected += pq * pp;
        if (li.qty !== pq) { reasons.push(`Quantity mismatch on "${p.item_description}": invoice ${li.qty}, PO ${pq}`); lineIssue = true; }
        if (Math.abs(li.price - pp) > Math.max(1, pp * PRICE_TOLERANCE_PCT / 100)) {
          reasons.push(`Price mismatch on "${p.item_description}": invoice ${rs(li.price)}, PO ${rs(pp)}`); lineIssue = true;
        }
      }
      expected = Math.round(expected * (1 + GST_RATE) * 100) / 100;
      if (!lineIssue && Math.abs(num(inv.total) - expected) > AMOUNT_TOLERANCE_RS) {
        const rate = num(inv.tax_rate_percent);
        const gstNote = rate && Math.abs(rate - GST_RATE * 100) > 0.01 ? ` (invoice charges ${rate}% GST, expected ${GST_RATE * 100}%)` : '';
        reasons.push(`Total mismatch: invoice ${rs(inv.total)}, expected ${rs(expected)}${gstNote}`);
      }
    }
  }

  results.push({
    json: {
      processed_at: new Date().toISOString().replace('T', ' ').slice(0, 19),
      invoice_number: inv.invoice_number || '',
      po_number: inv.po_number || '',
      vendor: inv.vendor_name || '',
      invoice_total: num(inv.total),
      expected_total: expected,
      status: reasons.length ? 'FLAGGED' : 'APPROVED',
      reasons: reasons.length ? reasons.join(' | ') : 'All checks passed',
      file_name: x.file_name,
      source: x.source,
    },
  });
}
return results;
